class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        c1 = c2 = c3 = 0
        for v in nums:
            if v == 1:
                c1 += 1
            elif v == 2:
                c2 = max(c2, c1) + 1
            else:
                c3 = max(c3, c1, c2) + 1
        return len(nums) - max(c1, c2, c3)

