class Solution {
    public int minimumOperations(List<Integer> nums) {
        int n = nums.size(), best = 1;
        int[] dp = new int[n];
        Arrays.fill(dp, 1);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++)
                if (nums.get(j) <= nums.get(i)) dp[i] = Math.max(dp[i], dp[j] + 1);
            best = Math.max(best, dp[i]);
        }
        return n - best;
    }
}

